using RuriLib.Functions.Crypto;
using System;
using System.Collections.Generic;
using System.Text;

namespace RuriLib.Models.Configs;

/// <summary>
/// Stores display and identity metadata for a config.
/// </summary>
public class ConfigMetadata
{
    /// <summary>
    /// The display name of the config.
    /// </summary>
    public string Name { get; set; } = "New Config";

    /// <summary>
    /// The category used to group the config.
    /// </summary>
    public string Category { get; set; } = "Default";

    /// <summary>
    /// The config author.
    /// </summary>
    public string Author { get; set; } = "Anonymous";

    /// <summary>
    /// The config image encoded as Base64.
    /// </summary>
    public string Base64Image { get; set; } = "";
    /// <summary>
    /// The creation timestamp.
    /// </summary>
    public DateTime CreationDate { get; set; }

    /// <summary>
    /// The last modification timestamp.
    /// </summary>
    public DateTime LastModified { get; set; }

    /// <summary>
    /// The plugins referenced by the config.
    /// </summary>
    public List<string> Plugins { get; set; } = [];

    /// <summary>
    /// Creates a new metadata instance with current timestamps.
    /// </summary>
    public ConfigMetadata()
    {
        CreationDate = DateTime.Now;
        LastModified = CreationDate;
    }

    /// <summary>
    /// Computes a hash that uniquely identifies the visible metadata state.
    /// </summary>
    /// <returns>The metadata hash.</returns>
    public byte[] GetUniqueHash()
        => Crypto.MD5(Encoding.UTF8.GetBytes(Name + Category + Author + Base64Image));
}
